package main

import (
	"fmt"
    "strings"
)
func main() {
    var q int
    fmt.Scan(&q)

    cartas := make([]int, q)

    for i := 0; i < q ; i++ {
        fmt.Scan(&cartas[i])
    }
    resultado := make([]string, q)


    for i, carta := range cartas {
        switch carta {
        case 1:
            resultado[i] = "A"
        case 11:
            resultado[i] = "J"
        case 12:
            resultado[i] = "Q"
        case 13:
            resultado[i] = "K"
        default:
            resultado[i] = fmt.Sprint(carta)
        }
    }
    fmt.Printf("[%s]\n",strings.Join(resultado, ", "))

    }
